/** @param {string} route @param {string} filename @param {import('../types/contracts').JsonObject} [value] */
async function downloadPdf(route, filename, value) {
  /** @type {Record<string, string>} */
  const headers = {};
  if (value) headers['Content-Type'] = 'application/json';
  const response = await fetch(route, {
    method: value ? 'POST' : 'GET',
    headers,
    body: value ? JSON.stringify(value) : undefined,
  });
  if (!response.ok) throw Error((await response.json()).error || 'PDF generation failed.');
  const url = URL.createObjectURL(await response.blob()),
    a = link('', url);
  a.download = filename;
  document.body.append(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
  notice(
    'PDF downloaded. Print at actual size, then scan it with the assigned terminal or ZmalaPhone app.',
  );
}
